	}
	trimmedLabel := strings.TrimSpace(label)
	indent := label[:len(label)-len(strings.TrimLeft(label, " \t"))]
	if indent == "" {
		indent = "  "
	}
	parts := make([]string, 0, len(facets))
	for _, facet := range facets {
		if styles.colorEnabled {
